-- NexoApp · 50 actividades de ejemplo (ficticias, hasta diciembre de 2026). Ejecútalo DESPUÉS de schema.sql.
-- Sin dueño (owner = null): nadie puede borrarlas desde la app, salvo un admin.
-- Es seguro correrlo más de una vez: si ya hay actividades de ejemplo, no inserta nada.
-- (Si ya tenías las primeras 24, usa seed-nov-dic.sql para agregar solo las nuevas.)
insert into public.activities (cat, title, host, loc, place, lat, lng, date, time, total, base_taken, description, status)
